    constexpr std::string_view GameKey(std::string_view pack, std::string_view key) {
        if (pack == "fo3") pack = "fnv";
        for (std::size_t i = 0; i < GamePacks.size(); ++i) {
            if (GamePacks[i] != pack) continue;
            for (const auto& entry : GameIcons)
                if (entry.key == key) return entry.art[i] == "none" ? std::string_view{} : entry.art[i];
            break;
        }
        return {};
    }
